const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  BorderStyle, Table, TableRow, TableCell, WidthType, ShadingType,
  Numbering, LevelFormat, PageBreak, convertInchesToTwip
} = require("docx");
const fs = require("fs");

const GOLD = "9C7A22";
const DARKGOLD = "6B531A";
const INK = "1A1A1A";
const MUTE = "5B5647";

const numbering = {
  config: [
    {
      reference: "clause-numbering",
      levels: [
        {
          level: 0,
          format: LevelFormat.DECIMAL,
          text: "%1.",
          alignment: AlignmentType.START,
          style: { paragraph: { indent: { left: 450, hanging: 300 } } },
        },
        {
          level: 1,
          format: LevelFormat.LOWER_LETTER,
          text: "(%2)",
          alignment: AlignmentType.START,
          style: { paragraph: { indent: { left: 900, hanging: 300 } } },
        },
      ],
    },
  ],
};

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 420, after: 160 },
    border: { bottom: { color: GOLD, space: 4, style: BorderStyle.SINGLE, size: 8 } },
    children: [new TextRun({ text, bold: true, color: DARKGOLD, size: 27, font: "Georgia" })],
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 140, line: 300 },
    children: [new TextRun({ text, size: 21, color: INK, italics: !!opts.italics, bold: !!opts.bold })],
  });
}

function clause(text, level = 0) {
  return new Paragraph({
    numbering: { reference: "clause-numbering", level },
    spacing: { after: 120, line: 300 },
    children: [new TextRun({ text, size: 21, color: INK })],
  });
}

function label(text) {
  return new Paragraph({
    spacing: { before: 60, after: 40 },
    children: [new TextRun({ text, bold: true, size: 20, color: DARKGOLD })],
  });
}

const doc = new Document({
  numbering,
  styles: {
    default: {
      document: { run: { font: "Calibri" } },
    },
  },
  sections: [
    {
      properties: {
        page: {
          size: { width: 12240, height: 15840 },
          margin: { top: 1000, bottom: 1000, left: 1200, right: 1200 },
        },
      },
      children: [
        // Title block
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 40 },
          children: [new TextRun({ text: "GP COMMITTEE", size: 18, color: MUTE, characterSpacing: 30 })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 60 },
          children: [new TextRun({ text: "THE GOLDEN POINT CHARTER", bold: true, size: 44, color: DARKGOLD, font: "Georgia" })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 100 },
          border: { bottom: { color: GOLD, space: 8, style: BorderStyle.SINGLE, size: 12 } },
          children: [new TextRun({ text: "Extended Terms & Conditions of Membership", italics: true, size: 24, color: INK, font: "Georgia" })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 160, after: 400 },
          children: [new TextRun({ text: "Issued by the GP Committee — Moniv Nautiyal · Sahil Malik · Akash Verma", size: 19, color: MUTE })],
        }),

        h1("1. Preamble"),
        body("The Golden Point is a single, extraordinary favour extended among the members of this Committee. It exists to formalise trust between friends: a favour significant enough to deserve rules, safeguards, and a name. This Charter is the extended terms and conditions referenced on the reverse of the physical Golden Point card, and it governs how the Point is granted, exercised, protected, and inherited."),
        body("This is a private, honour-based agreement between friends. It is not a legal contract, a registered financial instrument, or a bank product, and no clause here should be read as one.", { italics: true }),

        h1("2. Definitions"),
        clause("\u201cCard\u201d / \u201cGolden Point\u201d — the single-use favour represented physically by the Golden Point card."),
        clause("\u201cHolder\u201d / \u201cRedeemer\u201d — the Member whose turn it is to present, or who presents, the Golden Point."),
        clause("\u201cMember\u201d — an individual formally inducted per Section 5."),
        clause("\u201cCommittee\u201d — the GP Committee, currently Moniv Nautiyal, Sahil Malik, and Akash Verma."),
        clause("\u201cFD\u201d (Fixed Deposit) — the \u20b925,000 security commitment each Member maintains under Section 4."),

        h1("3. Rules of the Golden Point"),
        body("Carried forward from the physical card, unchanged:"),
        clause("The Golden Point grants its Holder a single, irrevocable request of their choosing."),
        clause("A presented request must be fulfilled. No designated Member may deny it, subject to the consequences in Section 4 if they do."),
        clause("The request may be of any type or nature. It is not limited to travel, destination, or category."),
        clause("The Point is valid only among Members formally listed with the Committee."),
        clause("Any addition to the Committee itself requires unanimous approval of all current Committee members."),

        h1("4. The Security Deposit (FD)"),
        clause("Every Member maintains a personal Fixed Deposit (FD) of \u20b925,000 as a standing security commitment tied to their membership of the Golden Point."),
        clause("The FD exists to give the \u201cmust be fulfilled\u201d rule real weight. It is the cost of saying no."),
        clause("Trigger conditions. A Member's FD is \u201cunlocked\u201d (forfeited for the Holder's use) if that Member:"),
        clause("Denies or refuses a validly presented Golden Point request, or", 1),
        clause("Misuses the Golden Point \u2014 for example, by inventing a request in bad faith or acting outside the spirit of Section 3 and this Charter.", 1),
        clause("Use of unlocked funds. Once a Member's FD is unlocked, the Holder who presented the Point may use that \u20b925,000 in any way they choose. It is not restricted to the original request."),
        clause("Illustrative example. Suppose Akash holds the Golden Point and asks the group to travel from Pune to Goa with him. If a Member refuses, that Member's FD unlocks, and Akash may use the \u20b925,000 however he wishes \u2014 including, but not limited to, funding the trip himself."),
        clause("Restoration. The Committee decides, by unanimous vote, whether and how a Member replenishes their FD after it has been unlocked."),

        h1("5. Becoming a Member"),
        clause("A prospective Member must first be included in the group's plans or activities on at least three (3) separate occasions."),
        clause("Meeting this threshold makes a person an \u201celigible contender.\u201d It does not itself grant membership."),
        clause("Eligible contenders are admitted only by unanimous vote of the GP Committee."),
        clause("Admission adds the new Member's name to the physical card and this Charter."),

        h1("6. Spirit of the Charter"),
        body("The Golden Point works because it is rarely, and seriously, invoked. Members are expected to act in good faith, both in presenting requests and in honouring them, and to treat the FD mechanism as a safeguard rather than a game to be gamed."),

        h1("7. Governance & Amendments"),
        clause("This Charter may only be amended by unanimous agreement of the GP Committee."),
        clause("The Committee is the final authority on any dispute arising from the use, denial, or misuse of a Golden Point."),

        h1("8. Disclaimer"),
        body("This Charter is an informal, honour-based agreement between friends. The \u201cFD\u201d described here is a private commitment between Members, not a regulated bank deposit, and this document creates no legal or financial obligation enforceable outside the group.", { italics: true }),

        new Paragraph({ spacing: { before: 500 }, children: [new PageBreak()] }),

        h1("Signatures"),
        body(" "),
        new Paragraph({ spacing: { before: 300, after: 60 }, children: [new TextRun({ text: "____________________________", size: 22 })] }),
        label("Moniv Nautiyal — GP Committee"),
        new Paragraph({ spacing: { before: 300, after: 60 }, children: [new TextRun({ text: "____________________________", size: 22 })] }),
        label("Sahil Malik — GP Committee"),
        new Paragraph({ spacing: { before: 300, after: 60 }, children: [new TextRun({ text: "____________________________", size: 22 })] }),
        label("Akash Verma — GP Committee"),
      ],
    },
  ],
});

Packer.toBuffer(doc).then((buf) => {
  fs.writeFileSync("/home/claude/gp/Golden-Point-Charter.docx", buf);
  console.log("written");
});

